package main

import (
	"context"
	"log/slog"
	"strings"

	restate "github.com/restatedev/sdk-go"
	"go.opentelemetry.io/otel/codes"

	"github.com/azylman/aerial/pkg/tracing"
)

const (
	spanPrefix      = "vanadis-restate."
	traceparentName = "traceparent"
)

// traceparentFromRequest picks the W3C traceparent for a Restate invocation. Attempt headers
// (generated by the Restate runtime when its own tracing is on) win so handler spans nest under
// Restate's invocation span; otherwise the original ingress headers carry the caller's context.
// Header keys are matched case-insensitively. Returns "" when neither carries one.
func traceparentFromRequest(attempt map[string][]string, headers map[string]string) string {
	for k, vals := range attempt {
		if strings.EqualFold(k, traceparentName) {
			for _, v := range vals {
				if v = strings.TrimSpace(v); v != "" {
					return v
				}
			}
		}
	}
	for k, v := range headers {
		if strings.EqualFold(k, traceparentName) {
			if v = strings.TrimSpace(v); v != "" {
				return v
			}
		}
	}
	return ""
}

// requestTraceparent extracts the traceparent from a Restate run or handler context.
func requestTraceparent(rc restate.RunContext) string {
	if rc == nil {
		return ""
	}
	req := rc.Request()
	if req == nil {
		return ""
	}
	var headers map[string]string
	if req.Headers != nil {
		headers = req.Headers.ToMap()
	}
	return traceparentFromRequest(req.AttemptHeaders, headers)
}

// tracedRunContext overrides the context.Context of a restate.RunContext with one carrying the
// active span, so HTTP calls made from a journaled step inherit the trace. Log and Request still
// come from the original run context.
type tracedRunContext struct {
	context.Context //nolint:containedctx // restate.RunContext embeds context.Context; the override carries the step span.

	base restate.RunContext
}

func (t tracedRunContext) Log() *slog.Logger         { return t.base.Log() }
func (t tracedRunContext) Request() *restate.Request { return t.base.Request() }

// runInSpan runs fn inside a span named name, parented on the invocation's traceparent, and
// hands fn a RunContext carrying that span. The span is closed before returning, and the
// return values pass through untouched, so what restate.Run journals does not change.
func runInSpan[T any](rc restate.RunContext, name string, fn func(restate.RunContext) (T, error)) (T, error) {
	ctx := tracing.ContextWithTraceparent(rc, requestTraceparent(rc))
	ctx, span := tracing.Tracer().Start(ctx, name)
	defer span.End()
	out, err := fn(tracedRunContext{Context: ctx, base: rc})
	if err != nil {
		span.SetStatus(codes.Error, tracing.Redact(err.Error()))
	}
	return out, err
}
